Certainly! Path search algorithms are used to find a route between nodes in a graph or a computer network. A common example is the Depth-First Search (DFS) algorithm. I'll implement both DFS and Breadth-First Search (BFS) algorithms for path finding.

For simplicity, let's consider an unweighted grid-based graph where we can move in four directions: up, down, left, and right. We'll use `Graph` class to represent the grid and the `path_search` function to perform the search.

```python
class Graph:
    def __init__(self, width, height):
        self.width = width
        self.height = height
        self.grid = [[' ' for _ in range(width)] for _ in range(height)]

    def set_start_end(self, start, end):
        self.start = (start[1], start[0])
        self.end = (end[1], end[0])

    def print_grid(self):
        for row in self.grid:
            print(' '.join(row))

    def get_neighbors(self, node):
        x, y = node
        neighbors = []
        if x > 0:  # left
            neighbors.append((x - 1, y))
        if x < self.width - 1:  # right
            neighbors.append((x + 1, y))
        if y > 0:  # up
            neighbors.append((x, y - 1))
        if y < self.height - 1:  # down
            neighbors.append((x, y + 1))
        return neighbors

def path_search(graph, start, end, algorithm='DFS'):
    """
    Perform path search using DFS or BFS.
    :param graph: Graph object representing the grid.
    :param start: Starting node (x, y).
    :param end: Ending node (x, y).
    :param algorithm: 'DFS' or 'BFS'. Default is 'DFS'.
    :return: Path from start to end if it exists, otherwise None.
    """
    if algorithm not in ['DFS', 'BFS']:
        raise ValueError("Algorithm must be 'DFS' or 'BFS'")

    def dfs(graph, start, end):
        stack = [(start, [start])]
        visited = set()
        while stack:
            (x, y), path = stack.pop()
            if (x, y) == end:
                return path
            for nx, ny in graph.get_neighbors((x, y)):
                if (nx, ny) not in visited and graph.grid[nx][ny] != '#':
                    visited.add((nx, ny))
                    stack.append(((nx, ny), path + [(nx, ny)]))
        return None

    def bfs(graph, start, end):
        queue = [(start, [start])]
        visited = set()
        while queue:
            (x, y), path = queue.pop(0)
            if (x, y) == end:
                return path
            for nx, ny in graph.get_neighbors((x, y)):
                if (nx, ny) not in visited and graph.grid[nx][ny] != '#':
                    visited.add((nx, ny))
                    queue.append(((nx, ny), path + [(nx, ny)]))
        return None

    if algorithm == 'DFS':
        return dfs(graph, start, end)
    elif algorithm == 'BFS':
        return bfs(graph, start, end)

